using System.Text;

public static class CaesarCipher
{
    public static string Encode(string text, int shift)
    {
        int s = ((shift % 26) + 26) % 26;
        var sb = new StringBuilder();
        foreach (char c in text)
        {
            if (c >= 'a' && c <= 'z')
            {
                sb.Append((char)('a' + (c - 'a' + s) % 26));
            }
            else if (c >= 'A' && c <= 'Z')
            {
                sb.Append((char)('A' + (c - 'A' + s) % 26));
            }
            else
            {
                sb.Append(c);
            }
        }
        return sb.ToString();
    }
}

