using Xunit;

public class CaesarCipherTests
{
    [Fact]
    public void BasicForwardShift()
    {
        Assert.Equal("def", CaesarCipher.Encode("abc", 3));
    }

    [Fact]
    public void WrapsAroundAlphabetEnd()
    {
        Assert.Equal("abc", CaesarCipher.Encode("xyz", 3));
    }

    [Fact]
    public void NegativeShiftWrapsBackward()
    {
        Assert.Equal("zab", CaesarCipher.Encode("abc", -1));
    }

    [Fact]
    public void PreservesCaseAndNonLetters()
    {
        Assert.Equal("Khoor, Zruog!", CaesarCipher.Encode("Hello, World!", 3));
    }
}

