using Xunit;

public class CaesarCipherTests
{
    [Fact]
    public void ReturnsSameLength()
    {
        Assert.Equal("abc".Length, CaesarCipher.Encode("abc", 3).Length);
    }

    [Fact]
    public void ShiftZeroIsIdentity()
    {
        Assert.Equal("abc", CaesarCipher.Encode("abc", 0));
    }

    [Fact]
    public void NotEmpty()
    {
        Assert.NotEmpty(CaesarCipher.Encode("abc", 5));
    }

    [Fact]
    public void Another()
    {
        Assert.Equal("abc".Length, CaesarCipher.Encode("abc", -3).Length);
    }
}
